"use client";

/**
 * Launch day film: title cards that say today is the day, a dive through
 * the main button into the product, a prompt composing itself, the people
 * who backed the launch, then an end card that asks for support. About 20
 * seconds at 1920 by 1080. Every scene is a Better Design video component,
 * cut together with the whip pan transition.
 *
 * Written by Better Design.
 */
import { linearTiming, TransitionSeries } from "@remotion/transitions";
import { Easing } from "remotion";
import { ButtonDive } from "@/components/bd-video/button-dive";
import { EndCard } from "@/components/bd-video/end-card";
import { PromptCompose } from "@/components/bd-video/prompt-compose";
import { SupporterGrid } from "@/components/bd-video/supporter-grid";
import { TitleCards } from "@/components/bd-video/title-cards";
import { whipPan } from "@/components/bd-video/transition-whip-pan";
import { type VideoTheme, VideoThemeProvider } from "@/lib/bd-video";

/** Every piece of copy, picture and number the launch day film shows. */
export interface LaunchDayFilmContent {
  /** The opening cards, shown in order. The last one should say you launch today. */
  cards: string[];
  /** A word on the last card that lands in the primary colour. */
  accent: string;
  /** The line above the button, and the text on it. */
  revealHeadline: string;
  buttonLabel: string;
  /** Picture of the product surface the camera dives into. A placeholder is drawn when unset. */
  screenshot?: string;
  /** The prompt that types itself, and the grey text in the empty field. */
  prompt: string;
  placeholder: string;
  /** Names drawn as initials in the supporter grid. */
  supporters: string[];
  /** The supporter count. `source` records where the figure comes from; it is not drawn. */
  supporterCount: { value: number; label: string; source: string };
  /** The thank-you line under the grid. */
  thanks: string;
  /** The product name on the end card. */
  name: string;
  /** The call for support on the end card button. */
  cta: string;
  /** The address where people can support the launch. */
  url: string;
}

const DEFAULT_CONTENT: LaunchDayFilmContent = {
  cards: ["We built this for a year.", "Today we launch."],
  accent: "launch",
  revealHeadline: "One click away.",
  buttonLabel: "Get started",
  prompt: "Draft a launch note for the new sharing feature, short and friendly",
  placeholder: "Ask anything",
  supporters: ["Maya Lin", "Jonas Keller", "Priya Shah", "Leo Marin", "Ines Rocha", "Sam Taylor", "Noor Aziz", "Theo Brandt", "Hana Watanabe", "Omar Diallo", "Lena Fischer", "Ravi Patel"],
  supporterCount: { value: 1240, label: "people joined the waitlist", source: "Replace with your own figure and its source" },
  thanks: "Thank you for building this with us.",
  name: "Your product",
  cta: "Support us today",
  url: "yourproduct.com/launch",
};

export interface LaunchDayFilmProps {
  content?: Partial<LaunchDayFilmContent>;
  theme?: Partial<VideoTheme>;
}

/** Frames per scene, in order: cards, button dive, prompt, supporters, end. */
const SCENES = [110, 120, 150, 120, 150] as const;
const CUT = 15;
const cut = () => <TransitionSeries.Transition presentation={whipPan({ direction: "left" })} timing={linearTiming({ durationInFrames: CUT, easing: Easing.bezier(0.7, 0, 0.3, 1) })} />;

/** A launch day film built from Better Design video components. */
export function LaunchDayFilm({ content, theme }: LaunchDayFilmProps) {
  const c = { ...DEFAULT_CONTENT, ...content };
  const count = { ...DEFAULT_CONTENT.supporterCount, ...content?.supporterCount };
  return (
    <VideoThemeProvider theme={theme}>
      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={SCENES[0]}>
          <TitleCards cards={c.cards} accent={c.accent} holdFrames={48} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[1]}>
          <ButtonDive label={c.buttonLabel} headline={c.revealHeadline} screenshot={c.screenshot} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[2]}>
          <PromptCompose prompt={c.prompt} placeholder={c.placeholder} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[3]}>
          <SupporterGrid names={c.supporters} count={count.value} countLabel={count.label} line={c.thanks} theme={theme} />
        </TransitionSeries.Sequence>
        {cut()}
        <TransitionSeries.Sequence durationInFrames={SCENES[4]}>
          <EndCard name={c.name} cta={c.cta} url={c.url} theme={theme} />
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </VideoThemeProvider>
  );
}

/** Composition settings. The duration is the scenes minus the four 15-frame cuts. */
export const LAUNCH_DAY_FILM = { durationInFrames: 590, fps: 30, width: 1920, height: 1080 } as const;
